## 3. 실전 활용 패턴

### 3.1 제네릭 API 응답 래퍼

모든 API 응답을 일관된 구조로 감싸는 패턴이다. `out T`를 사용하여 공변성을 부여한다.

```kotlin
data class ApiResponse<out T>(
    val data: T?,
    val error: String? = null,
    val status: Int = 200
) {
    val isSuccess: Boolean get() = error == null

    companion object {
        fun <T> success(data: T): ApiResponse<T> =
            ApiResponse(data = data)

        fun <T> success(data: T, status: Int): ApiResponse<T> =
            ApiResponse(data = data, status = status)

        fun error(message: String, status: Int = 500): ApiResponse<Nothing> =
            ApiResponse(data = null, error = message, status = status)
    }
}

// 사용 예시
fun getUser(id: Long): ApiResponse<User> {
    val user = userRepository.findById(id)
        ?: return ApiResponse.error("사용자를 찾을 수 없습니다", 404)
    return ApiResponse.success(user)
}

// out T 덕분에 ApiResponse<User>를 ApiResponse<Any>로 업캐스팅 가능
val response: ApiResponse<Any> = getUser(1L)

// Nothing은 모든 타입의 하위 타입이므로 error()의 반환 타입 ApiResponse<Nothing>은
// ApiResponse<User>, ApiResponse<String> 등 어디에나 대입 가능
```

> [!info] Nothing의 역할
> `ApiResponse.error()`가 `ApiResponse<Nothing>`을 반환하는 것이 핵심이다. `Nothing`은 모든 타입의 하위 타입이고, `out T`에 의해 `ApiResponse<Nothing>`은 모든 `ApiResponse<X>`의 하위 타입이 된다. 따라서 에러 응답을 어떤 타입의 `ApiResponse`에도 대입할 수 있다.

### 3.2 제네릭 이벤트 시스템

도메인 이벤트를 타입별로 핸들링하는 시스템이다. `in T`를 활용하여 상위 이벤트 핸들러가 하위 이벤트도 처리할 수 있게 한다.

```kotlin
// 도메인 이벤트 계층
interface DomainEvent {
    val occurredAt: java.time.Instant
}

data class OrderCreated(
    val orderId: Long,
    val userId: Long,
    override val occurredAt: java.time.Instant = java.time.Instant.now()
) : DomainEvent

data class PaymentCompleted(
    val paymentId: Long,
    val amount: Long,
    override val occurredAt: java.time.Instant = java.time.Instant.now()
) : DomainEvent

// 이벤트 핸들러 (in T: 반공변)
interface EventHandler<in T : DomainEvent> {
    fun handle(event: T)
}

class OrderCreatedHandler : EventHandler<OrderCreated> {
    override fun handle(event: OrderCreated) {
        println("주문 생성 처리: orderId=${event.orderId}")
    }
}

class PaymentCompletedHandler : EventHandler<PaymentCompleted> {
    override fun handle(event: PaymentCompleted) {
        println("결제 완료 처리: paymentId=${event.paymentId}, amount=${event.amount}")
    }
}

// 모든 이벤트를 로깅하는 범용 핸들러
class LoggingHandler : EventHandler<DomainEvent> {
    override fun handle(event: DomainEvent) {
        println("[LOG] ${event::class.simpleName} at ${event.occurredAt}")
    }
}

// in T 덕분에 EventHandler<DomainEvent>를 EventHandler<OrderCreated>로 사용 가능
val orderHandlers: List<EventHandler<OrderCreated>> = listOf(
    OrderCreatedHandler(),
    LoggingHandler()       // DomainEvent 핸들러를 OrderCreated 핸들러로 사용 가능
)

// 이벤트 디스패처
class EventDispatcher {
    private val handlers = mutableMapOf<Class<*>, MutableList<EventHandler<DomainEvent>>>()

    inline fun <reified T : DomainEvent> register(handler: EventHandler<T>) {
        val list = handlers.getOrPut(T::class.java) { mutableListOf() }
        @Suppress("UNCHECKED_CAST")
        list.add(handler as EventHandler<DomainEvent>)
    }

    fun <T : DomainEvent> dispatch(event: T) {
        handlers[event::class.java]?.forEach { it.handle(event) }
    }
}
```

### 3.3 제네릭 CRUD Repository 추상화

JPA를 사용한 공통 CRUD 로직을 제네릭으로 추상화하는 패턴이다.

```kotlin
// 기본 엔티티 인터페이스
interface BaseEntity<ID> {
    val id: ID?
}

// 제네릭 Repository 추상 클래스
abstract class BaseRepository<T : BaseEntity<ID>, ID>(
    private val entityClass: Class<T>
) {
    @PersistenceContext
    protected lateinit var em: EntityManager

    fun findById(id: ID): T? = em.find(entityClass, id)

    fun findAll(): List<T> {
        val query = em.createQuery("SELECT e FROM ${entityClass.simpleName} e", entityClass)
        return query.resultList
    }

    fun save(entity: T): T {
        return if (entity.id == null) {
            em.persist(entity)
            entity
        } else {
            em.merge(entity)
        }
    }

    fun delete(entity: T) {
        em.remove(if (em.contains(entity)) entity else em.merge(entity))
    }

    fun count(): Long {
        return em.createQuery(
            "SELECT COUNT(e) FROM ${entityClass.simpleName} e", Long::class.java
        ).singleResult
    }
}

// 구체적 Repository
@Repository
class UserRepository : BaseRepository<User, Long>(User::class.java) {
    fun findByEmail(email: String): User? {
        return em.createQuery(
            "SELECT u FROM User u WHERE u.email = :email", User::class.java
        ).setParameter("email", email)
            .resultList
            .firstOrNull()
    }
}

@Repository
class OrderRepository : BaseRepository<Order, Long>(Order::class.java) {
    fun findByUserId(userId: Long): List<Order> {
        return em.createQuery(
            "SELECT o FROM Order o WHERE o.userId = :userId", Order::class.java
        ).setParameter("userId", userId)
            .resultList
    }
}
```

